--
-- Table structure for table `Orders`
--

DROP TABLE IF EXISTS `Orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Orders` (
  `OrderID` int NOT NULL AUTO_INCREMENT,
  `CustomerID` int NOT NULL,
  `RestaurantID` int NOT NULL,
  `OrderDate` datetime NOT NULL,
  `EstimatedDelivery` datetime NOT NULL,
  `OrderStatus` enum('Placed','Preparing','Picked Up','Delivered','Cancelled') NOT NULL DEFAULT 'Placed',
  `DeliveryAddress` varchar(200) NOT NULL,
  `TotalAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`OrderID`),
  KEY `idx_orders_customer` (`CustomerID`),
  KEY `idx_orders_restaurant` (`RestaurantID`),
  KEY `idx_orders_date` (`OrderDate`),
  KEY `idx_orders_status` (`OrderStatus`),
  KEY `idx_order_date` (`OrderDate`),
  CONSTRAINT `fk_orders_customer` FOREIGN KEY (`CustomerID`) REFERENCES `Customers` (`CustomerID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_orders_restaurant` FOREIGN KEY (`RestaurantID`) REFERENCES `Restaurants` (`RestaurantID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_delivery_time` CHECK ((`EstimatedDelivery` > `OrderDate`)),
  CONSTRAINT `Orders_chk_1` CHECK ((`TotalAmount` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=299 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

