DROP TABLE IF EXISTS `Payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Payments` (
  `PaymentID` int NOT NULL AUTO_INCREMENT,
  `OrderID` int NOT NULL,
  `PaymentMethod` enum('UPI','Credit Card','Debit Card','Cash','Net Banking','Cash on Delivery','Wallet') NOT NULL,
  `PaymentStatus` enum('Success','Pending','Failed','Refunded') NOT NULL DEFAULT 'Pending',
  `PaymentDate` datetime NOT NULL,
  `Amount` decimal(10,2) NOT NULL,
  `RefundAmount` decimal(10,2) DEFAULT '0.00',
  `RefundDate` datetime DEFAULT NULL,
  `TransactionID` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`PaymentID`),
  UNIQUE KEY `OrderID` (`OrderID`),
  UNIQUE KEY `TransactionID` (`TransactionID`),
  CONSTRAINT `Payments_ibfk_1` FOREIGN KEY (`OrderID`) REFERENCES `Orders` (`OrderID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=299 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
