  CONSTRAINT `Reviews_ibfk_3` FOREIGN KEY (`RestaurantID`) REFERENCES `Restaurants` (`RestaurantID`),
  CONSTRAINT `Reviews_chk_1` CHECK ((`FoodRating` between 1 and 5)),
  CONSTRAINT `Reviews_chk_2` CHECK ((`DeliveryRating` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
